<script>
(function(){
  // ── Tab nav ──
  function bindTabs(){
    var tabs=document.querySelectorAll('.policy-tab'),docs=document.querySelectorAll('.policy-doc');
    if(!tabs.length) return;
    tabs.forEach(function(t){
      t.addEventListener('click',function(){
        var k=t.getAttribute('data-doc');
        tabs.forEach(function(x){var on=x===t;x.classList.toggle('active',on);x.setAttribute('aria-selected',String(on));});
        docs.forEach(function(d){d.classList.toggle('active',d.getAttribute('data-doc')===k);});
      });
    });
    if(location.hash==='#onsite'){var b=document.querySelector('.policy-tab[data-doc="onsite"]');b&&b.click();}
  }

  // ── Currency helpers — delegate to MAM_CCY (config.js) when present ──
  function detect(){
    if(window.MAM_CCY) return MAM_CCY.detect();
    try{var s=localStorage.getItem('mam.currency');if(s) return s;}catch(e){}
    var reg=((navigator.language||'').split('-')[1]||'').toUpperCase();
    return ({NG:'NGN',GH:'GHS',KE:'KES',ZA:'ZAR',GB:'GBP',IE:'EUR',DE:'EUR',FR:'EUR',US:'USD'}[reg])||'USD';
  }
  function sym(cur){
    if(window.MAM_CCY) return MAM_CCY.symbol(cur);
    return {USD:'$',NGN:'₦',GBP:'£',EUR:'€',GHS:'GH₵',KES:'KSh',ZAR:'R',CAD:'C$',AUD:'A$'}[cur]||(cur+' ');
  }
  function getRate(cur){
    if(window.MAM_CCY) return MAM_CCY.rate(cur);
    var base={USD:1,NGN:1500,GBP:0.79,EUR:0.92,GHS:15,KES:129,ZAR:18,CAD:1.37,AUD:1.52};
    try{var f=JSON.parse(localStorage.getItem('mam.fx')||'null');if(f&&f.rates) for(var k in f.rates) base[k]=f.rates[k];}catch(e){}
    return base[cur]||1;
  }
  function fxFresh(){
    try{var f=JSON.parse(localStorage.getItem('mam.fx')||'null');return !!(f&&f.t&&(Date.now()-f.t)<4*3600*1000);}catch(e){return false;}
  }

  // ── Format a fine amount (NGN contractual base → display currency) ──
  function fmtFine(ngnStr,usdHint,cur){
    var ngn=parseFloat(ngnStr)||0;
    if(cur==='NGN') return '₦'+ngn.toLocaleString('en-US');
    // For USD, use the known $/₦ contract pair where available; else live-convert
    if(cur==='USD'&&usdHint!=null){
      var u=parseFloat(usdHint)||0;
      return '$'+(u<1?u.toFixed(2):u.toLocaleString('en-US'));
    }
    var usd=ngn/getRate('NGN');
    if(window.MAM_CCY) return MAM_CCY.format(usd,cur);
    var v=usd*getRate(cur);
    if(v<1) return sym(cur)+v.toFixed(2);
    if(v<10) return sym(cur)+(Math.round(v*10)/10);
    return sym(cur)+Math.round(v).toLocaleString('en-US');
  }

  // ── Format a programme fee (USD base → display currency) ──
  function fmtAmt(usdStr,cur){
    var usd=parseFloat(usdStr)||0;
    if(window.MAM_CCY) return MAM_CCY.format(usd,cur);
    var v=usd*getRate(cur);
    if(v<1) return sym(cur)+v.toFixed(2);
    if(v<20) return sym(cur)+(Math.round(v*10)/10).toLocaleString('en-US');
    return sym(cur)+Math.round(v).toLocaleString('en-US');
  }

  // ── Paint all fine pills ──
  function paintFines(cur){
    document.querySelectorAll('.fine[data-fine-ngn]').forEach(function(el){
      el.textContent=fmtFine(el.getAttribute('data-fine-ngn'),el.getAttribute('data-fine-usd'),cur);
    });
  }

  // ── Paint all fee amount pills ──
  function paintAmounts(cur){
    document.querySelectorAll('.amt[data-amt-usd]').forEach(function(el){
      el.textContent=fmtAmt(el.getAttribute('data-amt-usd'),cur);
    });
  }

  // ── Update the live-rate note in the currency bar ──
  function updateRateNote(cur){
    var note=document.getElementById('pcRateNote');
    var dot=document.getElementById('pcDot');
    if(!note) return;
    var fresh=fxFresh();
    if(dot) dot.className='pc-dot'+(fresh?' live':'');
    if(cur==='NGN'){
      note.textContent='Contractual base — fines are fixed in Nigerian Naira';
    } else {
      var ngnPer=getRate('NGN'), targetPer=getRate(cur);
      // Show: $1 → local; ₦1,000 → local
      var localPerUsd=targetPer, localPer1kNgn=1000/ngnPer*targetPer;
      var usdLocal=sym(cur)+(localPerUsd<10?(Math.round(localPerUsd*100)/100):Math.round(localPerUsd).toLocaleString('en-US'));
      var ngnLocal=sym(cur)+(localPer1kNgn<1?localPer1kNgn.toFixed(2):(localPer1kNgn<10?Math.round(localPer1kNgn*10)/10:Math.round(localPer1kNgn).toLocaleString('en-US')));
      note.textContent='$1 ≈ '+usdLocal+' · ₦1,000 ≈ '+ngnLocal+(fresh?' · live rate':' · approx. rate');
    }
  }

  // ── Activate a currency (update buttons + repaint all amounts) ──
  function activate(cur){
    document.querySelectorAll('.pc-switch .currency-btn').forEach(function(b){
      var on=b.getAttribute('data-currency')===cur;
      b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));
    });
    paintFines(cur);
    paintAmounts(cur);
    updateRateNote(cur);
  }

  // ── Build switcher buttons dynamically — always include NGN + detected local ──
  function buildSwitcher(){
    var cur=detect();
    var set=['NGN','USD','GBP','EUR'];
    if(set.indexOf(cur)===-1) set.splice(1,0,cur); // inject local currency after NGN
    var sw=document.querySelector('.pc-switch');
    if(!sw) return;
    while(sw.firstChild) sw.removeChild(sw.firstChild);
    set.forEach(function(c){
      var b=document.createElement('button');
      b.className='currency-btn';
      b.setAttribute('data-currency',c);
      b.setAttribute('aria-selected','false');
      b.setAttribute('type','button');
      b.textContent=c;
      b.addEventListener('click',function(){
        try{localStorage.setItem('mam.currency',c);}catch(e){}
        activate(c);
      });
      sw.appendChild(b);
    });
  }

  // ── Watch for FX cache updates (main.js writes mam.fx after fetching live rates) ──
  function watchFx(){
    var seen='';
    setInterval(function(){
      var v=null;try{v=localStorage.getItem('mam.fx');}catch(e){}
      if(v&&v!==seen){seen=v;activate(detect());}
    },900);
    try{window.addEventListener('storage',function(e){if(e.key==='mam.fx'||e.key==='mam.currency') activate(detect());});}catch(e){}
  }

  function init(){buildSwitcher();bindTabs();activate(detect());watchFx();}
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init);
  else init();
})();
</script>
</body>
</html>
